script:
(function() {
  var COLORS = ['#ef4444','#3b82f6','#10b981','#f59e0b','#8b5cf6','#06b6d4','#f43f5e','#22c55e','#a78bfa','#fb923c'];
  function qs(s){ return root_element.querySelector(s); }
  function csrf(){ return (window.frappe && frappe.csrf_token) || ''; }
  function log(){ try { console.log.apply(console, ['[SCP]'].concat([].slice.call(arguments))); } catch(e){} }
  function fmt(n){ n = +n || 0; return n >= 1000 ? n.toLocaleString() : String(n); }
  function setText(sel, v){ var el = qs(sel); if (el) el.textContent = v; }

  // Poppins — loaded at document level so it reaches the shadow root.
  try {
    if (!document.querySelector('link[data-scp-poppins]')) {
      var pf=document.createElement('link'); pf.rel='stylesheet'; pf.setAttribute('data-scp-poppins','1');
      pf.href='https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap';
      document.head.appendChild(pf);
    }
  } catch(e){}

  var dateInput = qs('.scpx-date');
  var today = new Date().toISOString().slice(0, 10);
  if (dateInput) dateInput.value = today;

  /* ─────────────────────────  MAP  ───────────────────────── */
  var mapEl = qs('.scpmap-mapel');
  var lmap = null, zoneLayer = null, scoutLayer = null;
  var center = [-0.3, 36.9], zoom = 15, aborter = null;

  function showLoad(){ var o=qs('.scpmap-overlay'),e=qs('.scpmap-empty'); if(o)o.style.display='flex'; if(e)e.style.display='none'; }
  function hideLoad(empty){ var o=qs('.scpmap-overlay'),e=qs('.scpmap-empty'); if(o)o.style.display='none'; if(e)e.style.display=empty?'flex':'none'; }
  function kpi(cls,val){ var el=qs('.'+cls); if(el)el.textContent=val; }
  function resetKpis(){ kpi('scpmap-k-scouts',0); kpi('scpmap-k-beds',0); kpi('scpmap-k-zones',0); kpi('scpmap-k-mpb','0.0'); }

  function loadLeaflet(cb){
    // Block renders in a shadow root — Leaflet CSS must be injected INTO it.
    try {
      var host = (root_element && root_element.appendChild) ? root_element : document.head;
      if (host.querySelector && !host.querySelector('link[data-scp-leaflet]')) {
        var l=document.createElement('link'); l.rel='stylesheet'; l.href='/assets/frappe/js/lib/leaflet/leaflet.css'; l.setAttribute('data-scp-leaflet','1'); host.appendChild(l);
      }
    } catch(ex){}
    if (window.L) { cb(); return; }
    var s=document.createElement('script'); s.src='/assets/frappe/js/lib/leaflet/leaflet.js';
    s.onload=cb;
    s.onerror=function(){ console.error('[SCP] Leaflet failed to load'); hideLoad(true); var e=qs('.scpmap-empty'); if(e)e.textContent='Map library failed to load'; };
    document.head.appendChild(s);
  }

  function initMap(){
    if (lmap) { try { lmap.remove(); } catch(ex){} lmap=null; }
    if (mapEl && mapEl._leaflet_id) { mapEl._leaflet_id = null; }
    lmap = L.map(mapEl, { center:center, zoom:zoom, zoomControl:true, attributionControl:false });
    // Esri World Imagery — aerial, free, no API key.
    L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', { maxNativeZoom:19, maxZoom:21 }).addTo(lmap);
    zoneLayer = L.layerGroup().addTo(lmap);
    scoutLayer = L.layerGroup().addTo(lmap);
    setTimeout(function(){ try { if (lmap) lmap.invalidateSize(); } catch(ex){} }, 250);
  }

  function render(data){
    if (!lmap) return;
    zoneLayer.clearLayers(); scoutLayer.clearLayers();
    var zones=data.all_zones_geojson||[], entries=data.scouting_entries||[], summary=data.scouting_summary||{};
    var bounds=[], zoneCentroids={}, centroidList=[];
    zones.forEach(function(z){
      try {
        var gj=typeof z.raw_geojson==='string'?JSON.parse(z.raw_geojson):z.raw_geojson;
        var lyr=L.geoJSON(gj,{style:{color:'#22d3ee',weight:1.5,opacity:.45,fillOpacity:0},renderer:L.canvas()}).addTo(zoneLayer);
        try {
          var b=lyr.getBounds();
          if(b.isValid()){
            bounds.push([b.getSouth(),b.getWest()],[b.getNorth(),b.getEast()]);
            var c=b.getCenter();
            if(z.name){ zoneCentroids[z.name]=[c.lat,c.lng]; centroidList.push([c.lat,c.lng]); }
          }
        }catch(ex){}
      }catch(ex){}
    });

    // Snap a point to its zone centroid → clean zone-to-zone movement.
    function snapPoint(e){
      var z=(e.zone||'').replace(/^["'\s]+|["'\s]+$/g,'');
      if(z && zoneCentroids[z]) return zoneCentroids[z];
      if(e.latitude && e.longitude){
        var pt=[+e.latitude,+e.longitude], best=null, bd=Infinity;
        for(var k=0;k<centroidList.length;k++){ var dc=centroidList[k], dd=(dc[0]-pt[0])*(dc[0]-pt[0])+(dc[1]-pt[1])*(dc[1]-pt[1]); if(dd<bd){bd=dd;best=dc;} }
        return best||pt;
      }
      return null;
    }

    var groups={};
    entries.forEach(function(e){ var n=e.scouts_name||'Unknown'; if(!groups[n])groups[n]=[]; groups[n].push(e); });
    var names=Object.keys(groups);
    var legend=qs('.scpmap-legend');
    names.forEach(function(name,i){
      var color=COLORS[i%COLORS.length];
      var pts=[];
      groups[name].forEach(function(e){ var p=snapPoint(e); if(!p)return; var prev=pts[pts.length-1]; if(!prev||prev[0]!==p[0]||prev[1]!==p[1]) pts.push(p); });
      if(pts.length>1){
        L.polyline(pts,{color:color,weight:8,opacity:.22,lineCap:'round',lineJoin:'round',className:'scp-trail-glow'}).addTo(scoutLayer);
        L.polyline(pts,{color:color,weight:2.5,opacity:.95,lineCap:'round',lineJoin:'round',className:'scp-trail'}).addTo(scoutLayer);
      }
      if(pts.length>0){
        var last=pts[pts.length-1]; bounds.push(last);
        var icon=L.divIcon({className:'scp-scout-icon',iconSize:[14,14],iconAnchor:[7,7],
          html:'<span class="scp-ping" style="--sc:'+color+'"></span><span class="scp-core" style="--sc:'+color+'"></span>'});
        L.marker(last,{icon:icon,title:name}).bindTooltip(name,{permanent:false,direction:'top',offset:[0,-10]}).addTo(scoutLayer);
      }
    });
    if (legend){
      legend.innerHTML='';
      if(names.length>0){
        legend.style.display='flex';
        names.forEach(function(n,i){
          var item=document.createElement('div'); item.className='scpmap-legend-item';
          var dot=document.createElement('span'); dot.className='scpmap-legend-dot'; dot.style.background=COLORS[i%COLORS.length];
          item.appendChild(dot); item.appendChild(document.createTextNode(' '+n)); legend.appendChild(item);
        });
      } else { legend.style.display='none'; }
    }
    try { lmap.invalidateSize(); } catch(ex){}
    if(bounds.length>0){ try{ lmap.fitBounds(bounds,{padding:[30,30],maxZoom:19}); }catch(ex){} }
    kpi('scpmap-k-scouts', summary.total_unique_scouts!=null?summary.total_unique_scouts:names.length);
    kpi('scpmap-k-beds', summary.total_beds_covered||0);
    kpi('scpmap-k-zones', zones.length);
    kpi('scpmap-k-mpb', summary.average_minutes_per_bed?(+summary.average_minutes_per_bed).toFixed(1):'0.0');
  }

  function fetchAnalysis(dt){
    if(aborter)aborter.abort();
    aborter=new AbortController();
    return fetch('/api/method/upande_scp.serverscripts.get_scouting_analysis.getScoutingAnalysis',{
      method:'POST', headers:{'Content-Type':'application/json','X-Frappe-CSRF-Token':csrf()},
      body:JSON.stringify({date:dt}), signal:aborter.signal
    }).then(function(r){return r.json();}).then(function(r){return r.message||{};});
  }

  function latestScoutDate(){
    return fetch('/api/method/frappe.client.get_list',{
      method:'POST', headers:{'Content-Type':'application/json','X-Frappe-CSRF-Token':csrf()},
      body:JSON.stringify({doctype:'Scouting Entry', filters:[['latitude','is','set']], fields:['date_of_capture'], order_by:'date_of_capture desc', limit_page_length:1})
    }).then(function(r){return r.json();})
      .then(function(r){var rows=(r&&r.message)||[]; return rows.length?rows[0].date_of_capture:null;})
      .catch(function(){return null;});
  }

  function clearMap(){
    if(scoutLayer)scoutLayer.clearLayers();
    if(zoneLayer)zoneLayer.clearLayers();
    var lg=qs('.scpmap-legend'); if(lg){ lg.innerHTML=''; lg.style.display='none'; }
  }

  function loadMap(dt, allowFallback){
    showLoad();
    fetchAnalysis(dt).then(function(d){
      var entries=d.scouting_entries||[];
      if(!entries.length && allowFallback){
        return latestScoutDate().then(function(ld){
          if(ld && ld!==dt){ if(dateInput)dateInput.value=ld; return loadMap(ld,false); }
          clearMap(); hideLoad(true); resetKpis();
        });
      }
      if(!entries.length){ clearMap(); hideLoad(true); resetKpis(); return; }
      hideLoad(false); render(d);
    }).catch(function(e){ if(e&&e.name==='AbortError')return; console.error('[SCP] map load failed', e); hideLoad(true); resetKpis(); });
  }

  function bootMap(){
    loadLeaflet(function(){
      try { initMap(); } catch(ex){ console.error('[SCP] initMap failed', ex); hideLoad(true); var e=qs('.scpmap-empty'); if(e)e.textContent='Map failed to initialise'; return; }
      loadMap(today, true);
      setTimeout(function(){ var o=qs('.scpmap-overlay'); if(o && o.style.display!=='none'){ console.warn('[SCP] map watchdog fired'); hideLoad(true); resetKpis(); } }, 15000);
    });
  }

  /* ────────────────────────  SUMMARY  ──────────────────────── */
  var summaryDirty = true, summaryEverRendered = false;

  function chartInto(id, cfg){
    var el = qs('#' + id);
    if (!el || !window.frappe || !frappe.Chart) return;
    el.innerHTML = '';
    // frappe-charts draws its legend BELOW the chart height, so reserve room
    // for it — otherwise the legend row is clipped by the card.
    cfg.height = Math.max(140, (el.clientHeight || 300) - 48);
    try { new frappe.Chart(el, cfg); } catch(ex){ console.error('[SCP] chart failed', id, ex); }
  }

  function loadSummary(){
    var d = dateInput ? dateInput.value : today;
    fetch('/api/method/upande_scp.serverscripts.get_overview_summary.getOverviewSummary',{
      method:'POST', headers:{'Content-Type':'application/json','X-Frappe-CSRF-Token':csrf()},
      body:JSON.stringify({date:d})
    }).then(function(r){return r.json();}).then(function(r){
      var m=r.message||{}, k=m.kpis||{}, t=m.totals||{};
      setText('#scpx-k-scouts', fmt(k.scouts)); setText('#scpx-k-beds', fmt(k.beds));
      setText('#scpx-k-ghs', fmt(k.greenhouses)); setText('#scpx-k-obs', fmt(k.observations));
      var total=(t.pests||0)+(t.diseases||0)+(t.traps||0);
      var empty=qs('#scpx-summary-empty');
      if(!total){ if(empty)empty.style.display='flex'; summaryEverRendered=true; summaryDirty=false; return; }
      if(empty)empty.style.display='none';
      // Linear segments + visible dots (sharp points) — mirrors the frontend
      // Overview's Activity Timeline (recharts type="linear").
      chartInto('scpx-timeline', { type:'line', colors:['#22d3ee','#ec4899','#a855f7'],
        axisOptions:{xIsSeries:1}, lineOptions:{hideDots:0,regionFill:1,spline:0,dotSize:5},
        data:{ labels:m.labels||[], datasets:[
          {name:'Pests',values:m.pests||[]},{name:'Diseases',values:m.diseases||[]},{name:'Traps',values:m.traps||[]}
        ] } });
      chartInto('scpx-split', { type:'pie', animate:0, colors:['#22d3ee','#ec4899','#a855f7'],
        data:{ labels:['Pests','Diseases','Traps'], datasets:[{values:[t.pests||0,t.diseases||0,t.traps||0]}] } });
      summaryEverRendered=true; summaryDirty=false;
    }).catch(function(e){ console.error('[SCP] summary failed', e); });
  }

  function summaryActive(){ var p=qs('.scpx-pane-summary'); return p && p.classList.contains('active'); }

  /* ─────────────────────────  TABS  ───────────────────────── */
  root_element.querySelectorAll('.scpx-tab').forEach(function(btn){
    btn.addEventListener('click', function(){
      var tab=this.dataset.tab;
      root_element.querySelectorAll('.scpx-tab').forEach(function(b){ b.classList.remove('active'); });
      root_element.querySelectorAll('.scpx-pane').forEach(function(p){ p.classList.remove('active'); });
      this.classList.add('active');
      var pane=qs('.scpx-pane-'+tab); if(pane)pane.classList.add('active');
      if(tab==='map'){ setTimeout(function(){ try{ if(lmap)lmap.invalidateSize(); }catch(e){} }, 60); }
      else if(tab==='summary'){ if(summaryDirty || !summaryEverRendered) loadSummary(); }
    });
  });

  /* ───────────────  SHARED DATE (drives both)  ─────────────── */
  if(dateInput) dateInput.addEventListener('change', function(){
    loadMap(this.value, false);
    summaryDirty=true;
    if(summaryActive()) loadSummary();
  });

  /* ─────────────────────────  BOOT  ───────────────────────── */
  log('script start');
  fetch('/api/resource/Map%20Settings/Map%20Settings',{headers:{'X-Frappe-CSRF-Token':csrf()}})
    .then(function(r){return r.json();})
    .then(function(r){ var d=(r&&r.data)||{}; if(d.lat&&d.lon){ center=[+d.lat,+d.lon]; zoom=+d.default_zoom||15; } bootMap(); })
    .catch(function(){ bootMap(); });
})();

style:
/* ── One consolidated block: Map + Summary. ── */
.scpx{font-family:'Poppins',var(--font-stack),'Inter',sans-serif;background:var(--fg-color,#fff);border:1px solid var(--border-color,#e2e4e9);border-radius:14px;overflow:hidden}
.scpx-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 16px;border-bottom:1px solid var(--border-color,#e2e4e9)}

/* Pill switcher with smooth ease-in-out */
.scpx-tabs{display:inline-flex;gap:4px;background:var(--bg-color,#f4f5f7);border:1px solid var(--border-color,#e2e4e9);border-radius:999px;padding:4px;width:fit-content}
.scpx-tab{display:inline-flex;align-items:center;gap:7px;padding:7px 18px;border:none;background:transparent;color:var(--text-muted,#8a8f98);font-size:.82rem;font-weight:600;cursor:pointer;border-radius:999px;transition:background .2s ease-in-out,color .2s ease-in-out}
.scpx-tab.active{background:var(--primary,#2c7be5);color:#fff;box-shadow:0 1px 3px rgba(0,0,0,.12)}
.scpx-head-right{display:flex;align-items:center;gap:10px}
.scpx-live{display:inline-flex;align-items:center;gap:6px;font-size:.72rem;text-transform:uppercase;letter-spacing:.05em;color:var(--text-muted,#8a8f98);font-weight:600}
.scpx-live-dot{width:8px;height:8px;border-radius:50%;background:#10b981;display:inline-block;animation:scpx-pulse 2s ease-in-out infinite}
@keyframes scpx-pulse{0%,100%{box-shadow:0 0 0 0 rgba(16,185,129,.4)}50%{box-shadow:0 0 0 5px rgba(16,185,129,0)}}
.scpx-date{padding:6px 10px;border:1px solid var(--border-color,#e2e4e9);border-radius:8px;font-size:.8125rem;background:var(--bg-color,#fff);color:var(--text-color,#1c2126);outline:none}

/* Fixed-height body — both panes share the exact same box (no height jump). */
.scpx-body{position:relative;height:560px}
.scpx-pane{position:absolute;inset:0;display:none;flex-direction:column}
.scpx-pane.active{display:flex;animation:scpx-fade .28s cubic-bezier(.4,0,.2,1)}
@keyframes scpx-fade{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}

/* ── Map ── */
.scpmap-wrap{position:relative;flex:1;min-height:0;background:#0f172a}
.scpmap-mapel{width:100%;height:100%}
.scpmap-overlay{position:absolute;inset:0;z-index:1000;background:rgba(15,23,42,.66);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;color:#e5e7eb;font-size:.85rem;backdrop-filter:blur(1px)}
.scpmap-empty{display:none;position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);z-index:1000;background:rgba(15,23,42,.86);color:#e5e7eb;padding:16px 24px;border-radius:12px;flex-direction:column;align-items:center;gap:9px;font-size:.82rem;box-shadow:0 10px 30px rgba(0,0,0,.4);text-align:center}
.scpmap-legend{position:absolute;bottom:10px;right:10px;z-index:900;background:rgba(0,0,0,.7);color:#fff;border-radius:10px;padding:8px 12px;display:none;flex-direction:column;gap:5px;font-size:.74rem;max-height:190px;overflow-y:auto;backdrop-filter:blur(6px)}
.scpmap-legend-item{display:flex;align-items:center;gap:7px;white-space:nowrap}
.scpmap-legend-dot{width:9px;height:9px;border-radius:50%;flex-shrink:0}
.scpmap-kpi-row{display:flex;align-items:center;padding:10px 16px;border-top:1px solid var(--border-color,#e2e4e9);flex:0 0 auto}
.scpmap-kpi{display:flex;align-items:center;gap:9px;flex:1}
.scpmap-kpi-sep{width:1px;height:30px;background:var(--border-color,#e2e4e9);flex-shrink:0}
.scpmap-kpi-icon{width:30px;height:30px;border-radius:8px;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.scpmap-icon-scouts{background:rgba(59,130,246,.12);color:#3b82f6}
.scpmap-icon-beds{background:rgba(20,184,166,.12);color:#14b8a6}
.scpmap-icon-zones{background:rgba(16,185,129,.12);color:#10b981}
.scpmap-icon-mpb{background:rgba(245,158,11,.12);color:#f59e0b}
.scpmap-kpi-val{font-size:1.25rem;font-weight:700;color:var(--text-color,#1c2126);line-height:1.15}
.scpmap-kpi-label{font-size:.68rem;color:var(--text-muted,#8a8f98);text-transform:uppercase;letter-spacing:.5px;margin-top:1px}

/* Orbit loader (matches dashboard OrbitProgress) */
.scpmap-orbit{position:relative;width:56px;height:56px}
.scpmap-orbit svg{position:absolute;inset:0;overflow:visible}
.scpmap-orbit-track{stroke:#e5e7eb;opacity:.18}
.scpmap-orbit-arc{stroke:#38bdf8}
.scpmap-orbit-spin{transform-box:fill-box;transform-origin:center;animation:scpmap-orbit-spin 1.3s linear infinite}
@keyframes scpmap-orbit-spin{to{transform:rotate(360deg)}}

/* Hide tile attribution (per request) */
.leaflet-control-attribution{display:none!important}
/* Rounded zoom buttons, dark glass */
.leaflet-control-zoom{border:none!important;border-radius:14px!important;overflow:hidden;box-shadow:0 6px 18px rgba(0,0,0,.4)!important}
.leaflet-control-zoom a{width:32px;height:32px;line-height:32px;font-size:18px;font-weight:600;color:#e5e7eb!important;background:rgba(15,23,42,.82)!important;border:none!important;transition:background .15s,color .15s}
.leaflet-control-zoom a:first-child{border-radius:14px 14px 0 0!important}
.leaflet-control-zoom a:last-child{border-radius:0 0 14px 14px!important;border-top:1px solid rgba(255,255,255,.1)!important}
.leaflet-control-zoom a:hover{background:rgba(56,189,248,.92)!important;color:#0f172a!important}
.leaflet-control-zoom a.leaflet-disabled{opacity:.45;color:#94a3b8!important}

/* Sci-fi scout trails + radar-ping markers */
.scp-trail-glow{filter:blur(3px);animation:scp-glow 2.6s ease-in-out infinite}
@keyframes scp-glow{0%,100%{stroke-opacity:.16}50%{stroke-opacity:.32}}
.scp-scout-icon{background:transparent!important;border:none!important}
.scp-scout-icon .scp-core,.scp-scout-icon .scp-ping{position:absolute;left:50%;top:50%;width:13px;height:13px;border-radius:50%;transform:translate(-50%,-50%)}
.scp-scout-icon .scp-core{background:var(--sc);border:1.5px solid #fff;box-shadow:0 0 10px 2px var(--sc),0 0 4px #fff}
.scp-scout-icon .scp-ping{background:var(--sc);opacity:.55;animation:scp-ping 1.6s cubic-bezier(0,0,.2,1) infinite}
@keyframes scp-ping{0%{transform:translate(-50%,-50%) scale(1);opacity:.55}100%{transform:translate(-50%,-50%) scale(4.2);opacity:0}}

/* ── Summary ── */
.scpx-pane-summary{padding:14px 16px;gap:12px}
.scpx-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;flex:0 0 auto}
.scpx-kpi{border:1px solid var(--border-color,#e2e4e9);border-radius:10px;padding:12px 14px}
.scpx-kpi-val{font-size:1.5rem;font-weight:700;color:var(--text-color,#1c2126);line-height:1.1;font-variant-numeric:tabular-nums}
.scpx-kpi-label{font-size:.68rem;color:var(--text-muted,#8a8f98);text-transform:uppercase;letter-spacing:.5px;margin-top:3px}
.scpx-charts{flex:1;min-height:0;display:grid;grid-template-columns:1.4fr 1fr;gap:12px;position:relative}
.scpx-chart-card{border:1px solid var(--border-color,#e2e4e9);border-radius:12px;padding:10px 12px 4px;display:flex;flex-direction:column;min-height:0;overflow:hidden}
.scpx-chart-title{font-size:.72rem;font-weight:600;text-transform:uppercase;letter-spacing:.04em;color:var(--text-muted,#8a8f98);margin-bottom:2px}
.scpx-chart{flex:1;min-height:0}
/* keep the split's pie legend compact so all three items fit the column */
.scpx-split-card text{font-size:10px}
.scpx-split-card .chart-legend,.scpx-split-card .legend-dataset{font-size:10px}
/* Kill the pie's hover slice-shift/grow (paths only — not the centering <g>). */
.scpx-split-card svg path{transform:none!important;transition:none!important}
.scpx-summary-empty{display:none;position:absolute;inset:0;align-items:center;justify-content:center;background:var(--fg-color,#fff);color:var(--text-muted,#8a8f98);font-size:.85rem;text-align:center}

@media(max-width:820px){
  .scpx-body{height:auto}
  .scpx-pane{position:static}
  .scpmap-wrap{height:320px;flex:none}
  .scpx-kpis{grid-template-columns:repeat(2,1fr)}
  .scpx-charts{grid-template-columns:1fr;height:auto}
  .scpx-chart{height:260px}
}

script:
(function() {
  // Poppins — document-level so it reaches this block's shadow root.
  try {
    if (!document.querySelector('link[data-scp-poppins]')) {
      var pf=document.createElement('link'); pf.rel='stylesheet'; pf.setAttribute('data-scp-poppins','1');
      pf.href='https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap';
      document.head.appendChild(pf);
    }
  } catch(e){}

  // Role-gate the tiles: a tile with data-roles="" shows for everyone; otherwise
  // it shows only if the user holds one of the listed roles. System Manager /
  // Administrator always see everything.
  var roles = (window.frappe && frappe.user_roles) || [];
  var isAdmin = roles.indexOf('System Manager') >= 0
    || roles.indexOf('Administrator') >= 0
    || (window.frappe && frappe.user && frappe.user.name === 'Administrator');
  root_element.querySelectorAll('.scpn-tile').forEach(function(tile) {
    var req = (tile.getAttribute('data-roles') || '')
      .split(',').map(function(s){return s.trim();}).filter(Boolean);
    if (req.length === 0) return; // everyone
    var ok = isAdmin || req.some(function(r){ return roles.indexOf(r) >= 0; });
    if (!ok) tile.classList.add('scpn-hide');
  });
})();
